from sympy import *

c = 10**9 + 7

p, k = input().split()

p, k = int(p), int(k)

if k == 0:
	print((p ** (p - 1)) % c)

elif k == 1:
	print((p ** p) % c)

else:
	n = k
	order = 1
	while n != 1:
		n = (n * k) % p
		order += 1

	loops = (p - 1) // order
	print((p ** loops) % c)

