import operator

c = 10**9+7

p, k = map(int, input().split())

if k == 0:
	print(pow(p, p-1, c))
elif k == 1:
	print(pow(p, p, c))
else:
	def loop_multiply(p, k, n, order):
		if n == 1:
			return order
		else:
			n = (n*k) % p
			order += 1
			return loop_multiply(p, k, n, order)

	order = loop_multiply(p, k, k, 1)
	loops = (p-1) // order
	print(pow(p, loops, c))

