def powmod(base, exponent, modulus):
	if not exponent:
		return 1
	if not exponent % 2:
		return powmod((base * base) % modulus, exponent // 2, modulus)
	return (base * powmod(base, exponent - 1, modulus)) % modulus

if k == 0:
