from functools import lru_cache

c = 10**9+7
p, k = map(int, input().split())

@lru_cache(maxsize=None)
def powmod(p, k, level=1):
	if level == k:
		return p
	else:
		n = powmod(p, k, powmod(p, k-1, level))
		return (p * powmod(p, k-1, level)) % c

if k == 0:
	print(powmod(p, p-1))
elif k == 1:
	print(powmod(p, p))
else:
	n, order = k, 1
	while n != 1:
		n = (n*k) % p
		order += 1
	loops = (p-1) // order
	print(powmod(p, loops))

