def powmod(base, exponent, modulus):
	pow_dict = {0: 1, 1: base}
	for i in range(2, int(exponent) + 1):
		pow_dict[i] = (pow_dict[i-1] * pow_dict[1]) % modulus
	return pow_dict[int(exponent)]

